"""Hand-labelled screening cases (synthetic postings, synthetic candidates).

Labels are written from what each posting says, before running the code: they are test expectations, never
model or program output. `gates` lists only the gates a case is about; `verdict` is always checked.
"""
REQS='Requirements\n5+ years of experience implementing B2B SaaS\nSQL and data migration experience\nNice to have\nWorkday experience'
INTRO=('About the role\nYou will lead customer implementations from kickoff to go-live, working with product, support and the customer team '
       'to configure the platform, migrate data and train users. This is a full-time position.\n')
BASE={'posting_id':'synthetic:acme:1','board':'acme','title':'Implementation Manager','canonical_url':'https://jobs.example/acme/1',
      'locations':[{'text':'Remote, India','source':'location.name'}],'workplace_type':'Remote',
      'description':INTRO+REQS,'compensation_raw':'INR 30,00,000 - 40,00,000 per annum base'}
REVIEWED={'met':'profile: 7 years implementing SaaS platforms (synthetic)'}
def posting(pid,**changes):
    return BASE|{'posting_id':'synthetic:acme:'+pid}|changes
A,B='synthetic-impl-in','synthetic-design-eu'
EU_POSTING={'posting_id':'synthetic:initech:eu','board':'initech','title':'Product Designer','canonical_url':'https://jobs.example/initech/eu',
            'locations':[{'text':'Remote - Germany','source':'location.name'}],'workplace_type':'Remote',
            'description':'About the role\nDesign our onboarding product with Figma and a shared design system.\nRequirements\n3+ years of product design experience\nPortfolio of shipped work',
            'compensation_raw':'€70,000 - €85,000 base'}
CASES=[
    dict(id='ready_after_review',about='every gate supported; both mandatory requirements reviewed as met with profile evidence',
         candidate=A,posting=posting('1'),review_all=REVIEWED,expected={'verdict':'ready','gates':{g:'pass' for g in ('geography','engagement','qualifications','salary','application_history')}}),
    dict(id='pending_review_is_conditional',about='same posting without review decisions: qualifications stay unknown',
         candidate=A,posting=posting('1'),expected={'verdict':'conditional','gates':{'qualifications':'unknown','geography':'pass','salary':'pass'}}),
    dict(id='remote_us_only',about='remote but US only; India candidate',
         candidate=A,posting=posting('us',locations=[{'text':'Remote - US','source':'location.name'}]),expected={'verdict':'excluded','gates':{'geography':'fail'}}),
    dict(id='india_explicitly_allowed',about='location field says only Remote; text explicitly allows India',
         candidate=A,posting=posting('in',locations=[{'text':'Remote','source':'location.name'}],description=INTRO+'Candidates must be located in India or Sri Lanka.\n'+REQS),
         expected={'verdict':'conditional','gates':{'geography':'pass'}}),
    dict(id='worldwide_with_conflicting_country',about='listed worldwide, text requires US residence',
         candidate=A,posting=posting('ww',locations=[{'text':'Remote, Worldwide','source':'location.name'}],description=INTRO+'You must be based in the United States.\n'+REQS),
         expected={'verdict':'conditional','gates':{'geography':'unknown'}}),
    dict(id='negated_eligible_country',about='text says the employer cannot hire in India; never a pass',
         candidate=A,posting=posting('neg',locations=[{'text':'Remote','source':'location.name'}],description=INTRO+'We are unable to hire candidates located in India at this time.\n'+REQS),
         expected={'verdict':'conditional','gates':{'geography':'unknown'}}),
    dict(id='city_only_location',about='Pune is in India but cities are not recognised; unknown, not guessed',
         candidate=A,posting=posting('pune',locations=[{'text':'Pune','source':'location.name'}]),expected={'verdict':'conditional','gates':{'geography':'unknown'}}),
    dict(id='missing_salary',about='no pay anywhere',candidate=A,posting=posting('nopay',compensation_raw=None),
         expected={'verdict':'conditional','gates':{'salary':'unknown'}}),
    dict(id='variable_only_pay',about='only commission and bonus mentioned, no amount',candidate=A,posting=posting('var',compensation_raw='Uncapped commission • Offers Bonus'),
         expected={'verdict':'conditional','gates':{'salary':'unknown'}}),
    dict(id='range_spans_floor',about='20-30 lakh against a 25 lakh floor',candidate=A,posting=posting('span',compensation_raw='INR 20,00,000 - 30,00,000 per annum base'),
         expected={'verdict':'conditional','gates':{'salary':'unknown'}}),
    dict(id='range_below_floor',about='10-15 lakh against a 25 lakh floor',candidate=A,posting=posting('low',compensation_raw='INR 10,00,000 - 15,00,000 per annum base'),
         expected={'verdict':'excluded','gates':{'salary':'fail'}}),
    dict(id='lakh_units',about='₹30-40 LPA is 30-40 lakh per year, above the floor',candidate=A,posting=posting('lpa',compensation_raw='₹30-40 LPA base'),
         expected={'verdict':'conditional','gates':{'salary':'pass'}}),
    dict(id='ote_below_floor',about='OTE ceiling 22 lakh means base is below a 25 lakh base floor',candidate=A,
         posting=posting('ote',compensation_raw='Estimated OTE: INR 18,00,000 - 22,00,000 per annum'),expected={'verdict':'excluded','gates':{'salary':'fail'}}),
    dict(id='dollar_not_assumed_usd_or_inr',about='bare $ range for an INR floor: not comparable',candidate=A,posting=posting('usd',compensation_raw='$120K – $150K'),
         expected={'verdict':'conditional','gates':{'salary':'unknown'}}),
    dict(id='period_missing',about='INR range with no period; candidate A has no period assumption',candidate=A,
         posting=posting('noperiod',compensation_raw='INR 30,00,000 - 40,00,000 base'),expected={'verdict':'conditional','gates':{'salary':'unknown'}}),
    dict(id='mandatory_years_unmet',about='10+ years required, profile has 7',candidate=A,
         posting=posting('years',description=INTRO+'Requirements\n10+ years of experience in enterprise implementation\nSQL'),expected={'verdict':'excluded','gates':{'qualifications':'fail'}}),
    dict(id='preferred_years_unmet',about='12+ years only under Nice to have; not a mandatory failure',candidate=A,
         posting=posting('pref',description=INTRO+REQS+'\n12+ years of experience in enterprise software'),expected={'verdict':'conditional','gates':{'qualifications':'unknown'}}),
    dict(id='equivalent_years_not_automatic',about='8+ years or equivalent is not a mechanical shortfall',candidate=A,
         posting=posting('equiv',description=INTRO+'Requirements\n8+ years of experience or equivalent combination of education and experience'),expected={'verdict':'conditional','gates':{'qualifications':'unknown'}}),
    dict(id='required_language_missing',about='fluent French required; profile lists English and Hindi',candidate=A,
         posting=posting('fr',description=INTRO+REQS.replace('SQL and','Fluent French language skills (required)\nSQL and')),expected={'verdict':'excluded','gates':{'qualifications':'fail'}}),
    dict(id='reviewer_not_met',about='a reviewer marks a requirement not met with profile evidence',candidate=A,posting=posting('1'),
         review_all={'not_met':'profile: no data migration work recorded (synthetic)'},expected={'verdict':'excluded','gates':{'qualifications':'fail'}}),
    dict(id='already_applied',about='exact posting id in history',candidate=A,posting=posting('applied-1'),expected={'verdict':'excluded','gates':{'application_history':'fail'}}),
    dict(id='same_employer_same_title',about='history has acme Onboarding Lead; this is a different acme requisition with that title',
         candidate=A,posting=posting('reopen',title='Onboarding Lead'),expected={'verdict':'conditional','gates':{'application_history':'unknown'}}),
    dict(id='employer_cooldown',about='rejected by globex 25 days before today; cooldown 90 days',candidate=A,
         posting=posting('glx',board='globex',title='Implementation Manager'),today='2026-10-26',expected={'verdict':'excluded','gates':{'application_history':'fail'}}),
    dict(id='onsite_in_india',about='onsite in India: geography passes, remote-only engagement fails',candidate=A,
         posting=posting('blr',locations=[{'text':'Bengaluru, India','source':'location.name'}],workplace_type='OnSite',description=INTRO.replace(' This is a full-time position.','')+REQS),
         expected={'verdict':'excluded','gates':{'geography':'pass','engagement':'fail'}}),
    dict(id='workplace_conflict',about='location says remote, feed field says onsite',candidate=A,posting=posting('wc',workplace_type='OnSite'),
         expected={'verdict':'conditional','gates':{'engagement':'unknown'}}),
    dict(id='employment_type_unstated',about='no employment type wording; A accepts only full-time or contract',candidate=A,
         posting=posting('et',description=INTRO.replace(' This is a full-time position.','')+REQS),expected={'verdict':'conditional','gates':{'engagement':'unknown'}}),
    dict(id='empty_description',about='no description retrieved',candidate=A,posting=posting('empty',description=''),
         expected={'verdict':'conditional','gates':{'qualifications':'unknown'}}),
    dict(id='emea_for_india',about='EMEA does not include India',candidate=A,posting=posting('emea',locations=[{'text':'Remote - EMEA','source':'location.name'}]),
         expected={'verdict':'excluded','gates':{'geography':'fail'}}),
    dict(id='shared_posting_candidate_a',about='one EU posting assessed for two candidates: A is not eligible in Germany',candidate=A,posting=EU_POSTING,
         expected={'verdict':'excluded','gates':{'geography':'fail'}}),
    dict(id='shared_posting_candidate_b',about='same posting for B: Germany eligible, € unambiguous, period assumed by B\'s own rule',candidate=B,posting=EU_POSTING,
         expected={'verdict':'conditional','gates':{'geography':'pass','salary':'pass','engagement':'pass','application_history':'pass','qualifications':'unknown'}}),
    # Regressions found by screening the committed real postings (re-worded synthetically).
    dict(id='advantage_language_is_not_required',about='"fluency in French is a distinct advantage" sits in a requirements list',candidate=A,
         posting=posting('adv',description=INTRO+REQS.replace('SQL and','Professional fluency in French is a distinct advantage.\nSQL and')),
         expected={'verdict':'conditional','gates':{'qualifications':'unknown'}}),
    dict(id='years_alternatives_use_lower_bar',about='6+ years in X or 9+ years in Y; profile has 7',candidate=A,
         posting=posting('alt',description=INTRO+'Requirements\n6+ years of implementation experience or 9+ years of professional services experience'),
         expected={'verdict':'conditional','gates':{'qualifications':'unknown'}}),
    dict(id='or_without_years',about='a requirement with "or" and no year figure stays pending',candidate=A,
         posting=posting('orx',description=INTRO+'Requirements\nExperience with SaaS or PaaS platforms'),expected={'verdict':'conditional','gates':{'qualifications':'unknown'}}),
    dict(id='team_description_is_not_a_location_rule',about='a negated sentence about a global team is not about where the person works',candidate=A,
         posting=posting('team',description=INTRO+'Our support team is a global group across AMER, EMEA and APAC, digging into why something is not working.\n'+REQS),
         expected={'verdict':'conditional','gates':{'geography':'pass'}}),
    dict(id='negation_in_another_clause',about='"outside your local hours" in a later clause does not negate "based in APJ"',candidate=A,
         posting=posting('apj',locations=[{'text':'Remote','source':'location.name'}],
                         description=INTRO+'This role is based in the APJ region. Written handoffs matter more than availability outside your local hours.\n'+REQS),
         expected={'verdict':'conditional','gates':{'geography':'pass'}}),
    dict(id='global_listing_with_regional_restriction',about='listed Remote (Global) but applications only from the Americas or Europe',candidate=A,
         posting=posting('glob',locations=[{'text':'Remote (Global)','source':'location'}],
                         description=INTRO+'Please note: We are currently accepting applications only from candidates based in North America, South America or Europe.\n'+REQS),
         expected={'verdict':'conditional','gates':{'geography':'unknown'}}),
    dict(id='emea_for_eu_candidate',about='EMEA includes Germany; B has no salary gate requirement listed, so default all five are required',candidate=B,
         posting=EU_POSTING|{'posting_id':'synthetic:initech:emea','locations':[{'text':'Remote - EMEA','source':'location.name'}]},
         expected={'verdict':'conditional','gates':{'geography':'pass'}}),
]
